// Ray casting: true si el punto (lat, lng) cae dentro del anillo dado.
function puntoEnAnillo(lat: number, lng: number, anillo: [number, number][]): boolean {
  let dentro = false;
  for (let i = 0, j = anillo.length - 1; i < anillo.length; j = i++) {
    const [lngI, latI] = anillo[i];
    const [lngJ, latJ] = anillo[j];
    const interseca =
      latI > lat !== latJ > lat &&
      lng < ((lngJ - lngI) * (lat - latI)) / (latJ - latI) + lngI;
    if (interseca) dentro = !dentro;
  }
  return dentro;
}

/** Nombre oficial del barrio (dataset municipal) que contiene el punto, o null. */
export function resolverBarrioPorCoordenadas(
  lat: number,
  lng: number,
): string | null {
  for (const b of BARRIOS_POLIGONOS) {
    if (b.anillos.some((anillo) => puntoEnAnillo(lat, lng, anillo))) {
      return b.nombre;
    }
  }
  return null;
}

function distanciaAprox(a: { lat: number; lng: number }, b: { lat: number; lng: number }): number {
  const dLat = a.lat - b.lat;
  const dLng = a.lng - b.lng;
  return Math.sqrt(dLat * dLat + dLng * dLng);
}

/** Nombre oficial del barrio cuyo polígono está geográficamente más cerca del punto
 * (fallback para cuando el punto no cae dentro de ningún polígono — ej. veredas
 * límite, error de geocodificación, terrenos sin relevar). Usa la distancia al
 * primer vértice de cada anillo como aproximación rápida, suficiente para elegir
 * "el barrio vecino más cercano" sin calcular centroides reales. */
export function barrioMasCercano(lat: number, lng: number): string | null {
  let mejor: string | null = null;
  let mejorDist = Infinity;
  for (const b of BARRIOS_POLIGONOS) {
    for (const anillo of b.anillos) {
      for (const [lngV, latV] of anillo) {
        const d = distanciaAprox({ lat, lng }, { lat: latV, lng: lngV });
        if (d < mejorDist) {
          mejorDist = d;
          mejor = b.nombre;
        }
      }
    }
  }
  return mejor;
}
